    const y = Math.max(0, -top);
    const w = Math.min(fullWidth - x, width - Math.max(0, left));
    const h = Math.min(fullHeight - y, height - Math.max(0, top));
    return w > 0 && h > 0 ? { left: x, top: y, width: w, height: h } : null;
}
async function visibleScaledAsset(input, fullWidth, fullHeight, region, cache, key) {
    const existing = cache.get(key);
    if (existing) return existing;
    const data = await sharp(input)
        .resize(fullWidth, fullHeight, { kernel: sharp.kernel.lanczos3 })
        .extract(region).ensureAlpha().raw().toBuffer();
    const asset = { data, width: region.width, height: region.height };
    cacheRecordingCardAsset(cache, key, asset);
    return asset;
}
async function renderBackgroundCard(frame, width, height, zoomState, background) {
    const center = zoomStateToTravelCenter(width, height, zoomState);
    const rect = calculateRecordingCardRect(background.inset, zoomState.scale, center.sx, center.sy);
    const cardWidth = Math.max(1, Math.round(rect.width));
    const cardHeight = Math.max(1, Math.round(rect.height));
    const cardLeft = Math.round(rect.left);
    const cardTop = Math.round(rect.top);
    const region = visibleRegion(cardWidth, cardHeight, cardLeft, cardTop, width, height);
    const cache = getRecordingCardAssetCache(background);
    const overlays = [];
    const scale = cardWidth / background.inset.width;
    const sw = Math.max(1, Math.round(background.shadow.width * scale));
    const sh = Math.max(1, Math.round(background.shadow.height * scale));
    const sl = Math.round(rect.left + background.shadow.leftOffset * scale);
    const st = Math.round(rect.top + background.shadow.topOffset * scale);
    const shadowRegion = visibleRegion(sw, sh, sl, st, width, height);
    if (shadowRegion) {
        const shadow = await visibleScaledAsset(background.shadow.tilePng, sw, sh, shadowRegion, cache.shadows, JSON.stringify([sw,sh,shadowRegion]));
        overlays.push({ input: shadow.data, raw: {width: shadow.width,height: shadow.height,channels:4}, left:Math.max(0,sl),top:Math.max(0,st) });
    }
    if (region) {
        const mask = await visibleScaledAsset(background.maskPng, cardWidth, cardHeight, region, cache.masks, JSON.stringify([cardWidth,cardHeight,region]));
        const raw = {width:region.width,height:region.height,channels:4};
        const card = await sharp(frame, {raw:{width,height,channels:4}})
            .resize(cardWidth,cardHeight,{kernel:sharp.kernel.lanczos3})
            .extract(region).composite([{input:mask.data,raw,blend:"dest-in"}]).raw().toBuffer();
        overlays.push({input:card,raw,left:Math.max(0,cardLeft),top:Math.max(0,cardTop)});
    }
    return sharp(background.plateRgba,{raw:{width,height,channels:4}}).composite(overlays).raw().toBuffer();
}
